import React, { useState } from 'react'; // Добавьте импорт useState
import { Link, useNavigate } from 'react-router-dom';


const Footer = () => {
  const [email, setEmail] = useState('');
  const [subscribed, setSubscribed] = useState(false);

  const handleSubscribe = (e) => {
    e.preventDefault();
    if (email) {
      setSubscribed(true);
      setEmail('');
      setTimeout(() => setSubscribed(false), 3000);
    }
  };

  return (
    <footer className="bg-gray-900 text-white">
      <div className="max-w-7xl mx-auto px-4 py-12">
        <div className="grid grid-cols-1 md:grid-cols-4 gap-8">
          {/* Brand */}
          <div>
            <h3 className="text-xl font-serif font-bold mb-4">LUNA AUREA</h3>
            <p className="text-gray-400">Уникальные украшения ручной работы</p>
          </div>

          {/* Menu */}
          <div className="hidden md:flex space-x-8">
            <h4 className="font-semibold mb-4">МЕНЮ</h4>
            <ul className="space-y-2">
              <li><a href="#catalog" className="text-gray-400 hover:text-white">Коллекции</a></li>
              <Link to="/catalog" className="text-gray-700 hover:text-gold-600">КАТАЛОГ</Link>
              <li><a href="#about" className="text-gray-400 hover:text-white">О нас</a></li>
            </ul>
          </div>

          {/* Help */}
          <div>
            <h4 className="font-semibold mb-4">ПОМОЩЬ</h4>
            <ul className="space-y-2">
              <li><a href="#delivery" className="text-gray-400 hover:text-white">Доставка</a></li>
              <li><a href="#payment" className="text-gray-400 hover:text-white">Оплата</a></li>
              <li><a href="#contacts" className="text-gray-400 hover:text-white">Контакты</a></li>
            </ul>
          </div>

          {/* Subscription */}
          <div>
            <h4 className="font-semibold mb-4">ПОДПИСКА</h4>
            <p className="text-gray-400 mb-4">Будьте в курсе новинок</p>
            <form onSubmit={handleSubscribe} className="flex">
              <input
                type="email"
                placeholder="Email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="px-3 py-2 bg-gray-800 text-white rounded-l focus:outline-none focus:ring-2 focus:ring-gold-500 flex-grow"
                required
              />
              <button
                type="submit"
                className="bg-gold-600 hover:bg-gold-700 px-4 py-2 rounded-r"
              >
                ✓
              </button>
            </form>
            {subscribed && (
              <div className="mt-2 p-2 bg-green-600 rounded text-sm">
                Спасибо за подписку!
              </div>
            )}
          </div>
        </div>
      </div>
    </footer>
  );
};

export default Footer;
